-- Stage7 append-only platform management, immutable versions and tenant template mappings.
CREATE TABLE subject_packs(key TEXT PRIMARY KEY,name TEXT NOT NULL,current_published_version TEXT,created_at INTEGER NOT NULL);
CREATE TABLE subject_pack_versions(key TEXT NOT NULL REFERENCES subject_packs(key),pack_version TEXT NOT NULL,name TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,status TEXT NOT NULL CHECK(status IN('draft','published')),content_json TEXT NOT NULL CHECK(json_valid(content_json)),created_at INTEGER NOT NULL,created_by TEXT NOT NULL,updated_at INTEGER NOT NULL,updated_by TEXT NOT NULL,published_at INTEGER,PRIMARY KEY(key,pack_version));
CREATE TRIGGER subject_version_immutable BEFORE UPDATE ON subject_pack_versions WHEN OLD.status='published' BEGIN SELECT RAISE(ABORT,'subject_version_immutable'); END;
CREATE TABLE setting_template_refs(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,subject TEXT NOT NULL,kind TEXT NOT NULL,template_key TEXT NOT NULL,entity_id TEXT NOT NULL,PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,subject,kind,template_key));
CREATE TABLE style_version_meta(pack_id TEXT NOT NULL REFERENCES style_packs(id),pack_version TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,status TEXT NOT NULL CHECK(status IN('draft','published')),scope TEXT NOT NULL CHECK(scope IN('admin_only','tenants','all')),checks_json TEXT NOT NULL CHECK(json_valid(checks_json)),created_by TEXT NOT NULL,published_at INTEGER,PRIMARY KEY(pack_id,pack_version),FOREIGN KEY(pack_id,pack_version) REFERENCES style_pack_versions(pack_id,version));
CREATE TRIGGER style_meta_immutable BEFORE UPDATE ON style_version_meta WHEN OLD.status='published' BEGIN SELECT RAISE(ABORT,'style_meta_immutable'); END;
CREATE TABLE style_version_tenants(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,pack_id TEXT NOT NULL,pack_version TEXT NOT NULL,PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,pack_id,pack_version),FOREIGN KEY(pack_id,pack_version) REFERENCES style_version_meta(pack_id,pack_version));
CREATE TABLE style_assets(pack_id TEXT NOT NULL,pack_version TEXT NOT NULL,path TEXT NOT NULL,r2_key TEXT NOT NULL,mime TEXT NOT NULL,width INTEGER NOT NULL,height INTEGER NOT NULL,bytes INTEGER NOT NULL,sha256 TEXT NOT NULL,PRIMARY KEY(pack_id,pack_version,path),FOREIGN KEY(pack_id,pack_version) REFERENCES style_pack_versions(pack_id,version));
CREATE TRIGGER style_asset_immutable BEFORE UPDATE ON style_assets BEGIN SELECT RAISE(ABORT,'style_asset_immutable'); END;
CREATE TABLE style_defaults(doc_type TEXT PRIMARY KEY,pack_id TEXT NOT NULL REFERENCES style_packs(id));
CREATE TABLE platform_ops_guards(id TEXT PRIMARY KEY,expected INTEGER NOT NULL,actual INTEGER NOT NULL,CHECK(expected=actual));
CREATE INDEX setting_template_entity ON setting_template_refs(tenant_id,entity_id);
